// C documentation
//
//	// Unlinks and removes all thread states from `tstate->interp`, with the
//	// exception of the one passed as an argument. However, it does not delete
//	// these thread states. Instead, it returns the removed thread states as a
//	// linked list.
//	//
//	// Note that if there is a current thread state, it *must* be the one
//	// passed as argument.  Also, this won't touch any interpreters other
//	// than the current one, since we don't know which thread state should
//	// be kept in those other interpreters.
func X_PyThreadState_RemoveExcept(tls *libc.TLS, tstate uintptr) (r uintptr) {
	bp := tls.Alloc(16)
	defer tls.Free(16)
	var interp, list, runtime, v1 uintptr
	var _ Tuint8_t
	var _ Tuint8_t
	_, _, _, _ = interp, list, runtime, v1
	interp = (*TPyThreadState)(unsafe.Pointer(tstate)).Finterp
	runtime = (*TPyInterpreterState)(unsafe.Pointer(interp)).Fruntime
	v1 = runtime + 800
	**(**Tuint8_t)(__ccgo_up(bp + 1)) = uint8(M_Py_UNLOCKED)
	if !(__Py_atomic_compare_exchange_uint8(tls, v1, bp+1, uint8(M_Py_LOCKED)) != 0) {
		X_PyMutex_LockTimed(tls, v1, int64(-int32(1)), int32(E_Py_LOCK_DONT_DETACH))
	}

	list = (*TPyInterpreterState)(unsafe.Pointer(interp)).Fthreads.Fhead
	if list == tstate {
		list = (*TPyThreadState)(unsafe.Pointer(tstate)).Fnext
	}
	if (*TPyThreadState)(unsafe.Pointer(tstate)).Fprev != 0 {
		(*TPyThreadState)(unsafe.Pointer((*TPyThreadState)(unsafe.Pointer(tstate)).Fprev)).Fnext = (*TPyThreadState)(unsafe.Pointer(tstate)).Fnext
	}
	if (*TPyThreadState)(unsafe.Pointer(tstate)).Fnext != 0 {
		(*TPyThreadState)(unsafe.Pointer((*TPyThreadState)(unsafe.Pointer(tstate)).Fnext)).Fprev = (*TPyThreadState)(unsafe.Pointer(tstate)).Fprev
	}
	v1 = libc.UintptrFromInt32(0)
	(*TPyThreadState)(unsafe.Pointer(tstate)).Fnext = v1
	(*TPyThreadState)(unsafe.Pointer(tstate)).Fprev = v1
	(*TPyInterpreterState)(unsafe.Pointer(interp)).Fthreads.Fhead = tstate
	v1 = runtime + 800
	**(**Tuint8_t)(__ccgo_up(bp)) = uint8(M_Py_LOCKED)
	if !(__Py_atomic_compare_exchange_uint8(tls, v1, bp, uint8(M_Py_UNLOCKED)) != 0) {
		XPyMutex_Unlock(tls, v1)
	}
	return list
}

