func X_PyTimeFraction_Mul(tls *libc.TLS, ticks TPyTime_t, frac uintptr) (r TPyTime_t) {
	var div, intpart, mul, remaining TPyTime_t
	_, _, _, _ = div, intpart, mul, remaining
	mul = (*T_PyTimeFraction)(unsafe.Pointer(frac)).Fnumer
	div = (*T_PyTimeFraction)(unsafe.Pointer(frac)).Fdenom
	if div == int64(1) {

		return __PyTime_Mul(tls, ticks, mul)
	}
	intpart = ticks / div
	ticks = ticks % div
	remaining = __PyTime_Mul(tls, ticks, mul) / div

	return X_PyTime_Add(tls, __PyTime_Mul(tls, intpart, mul), remaining)
}

