//	an element equal to key, return the position immediately to the left of
//	the leftmost equal element.  [gallop_right() does the same except returns
//	the position to the right of the rightmost equal element (if any).]
//
//	"a" is a sorted vector with n elements, starting at a[0].  n must be > 0.
//
//	"hint" is an index at which to begin the search, 0 <= hint < n.  The closer
//	hint is to the final result, the faster this runs.
//
//	The return value is the int k in 0..n such that
//
//	    a[k-1] < key <= a[k]
//
//	pretending that *(a-1) is minus infinity and a[n] is plus infinity.  IOW,
//	key belongs at index k; or, IOW, the first k elements of a should precede
//	key, and the last n-k should follow key.
//
//	Returns -1 on error.  See listsort.txt for info on the method.
//	*/
func _gallop_left(tls *libc.TLS, ms uintptr, key uintptr, a uintptr, n TPy_ssize_t, hint TPy_ssize_t) (r TPy_ssize_t) {
	var k, lastofs, m, maxofs, maxofs1, ofs, v1 TPy_ssize_t
	_, _, _, _, _, _, _ = k, lastofs, m, maxofs, maxofs1, ofs, v1
	a = a + uintptr(hint)*8
	lastofs = 0
	ofs = int64(1)
	v1 = int64((*(*func(*libc.TLS, uintptr, uintptr, uintptr) int32)(unsafe.Pointer(&struct{ uintptr }{(*TMergeState)(unsafe.Pointer(ms)).Fkey_compare})))(tls, **(**uintptr)(__ccgo_up(a)), key, ms))
	k = v1
	if v1 < 0 {
		goto fail
	}
	if k != 0 {

		maxofs = n - hint
		for ofs < maxofs {
			v1 = int64((*(*func(*libc.TLS, uintptr, uintptr, uintptr) int32)(unsafe.Pointer(&struct{ uintptr }{(*TMergeState)(unsafe.Pointer(ms)).Fkey_compare})))(tls, **(**uintptr)(__ccgo_up(a + uintptr(ofs)*8)), key, ms))
			k = v1
			if v1 < 0 {
				goto fail
			}
			if k != 0 {
				lastofs = ofs
				ofs = ofs<<libc.Int32FromInt32(1) + int64(1)
			} else {
				break
			}
		}
		if ofs > maxofs {
			ofs = maxofs
		}

		lastofs = lastofs + hint
		ofs = ofs + hint
	} else {

		maxofs1 = hint + int64(1)
		for ofs < maxofs1 {
			v1 = int64((*(*func(*libc.TLS, uintptr, uintptr, uintptr) int32)(unsafe.Pointer(&struct{ uintptr }{(*TMergeState)(unsafe.Pointer(ms)).Fkey_compare})))(tls, **(**uintptr)(__ccgo_up(a - uintptr(ofs)*8)), key, ms))
			k = v1
			if v1 < 0 {
				goto fail
			}
			if k != 0 {
				break
			}

			lastofs = ofs
			ofs = ofs<<libc.Int32FromInt32(1) + int64(1)
		}
		if ofs > maxofs1 {
			ofs = maxofs1
		}

		k = lastofs
		lastofs = hint - ofs
		ofs = hint - k
	}
	a = a - uintptr(hint)*8

	lastofs = lastofs + 1
	for lastofs < ofs {
		m = lastofs + (ofs-lastofs)>>int32(1)
		v1 = int64((*(*func(*libc.TLS, uintptr, uintptr, uintptr) int32)(unsafe.Pointer(&struct{ uintptr }{(*TMergeState)(unsafe.Pointer(ms)).Fkey_compare})))(tls, **(**uintptr)(__ccgo_up(a + uintptr(m)*8)), key, ms))
		k = v1
		if v1 < 0 {
			goto fail
		}
		if k != 0 {
			lastofs = m + int64(1)
		} else {
			ofs = m
		}
	}

	return ofs
	goto fail
fail:
	;
	return int64(-int32(1))
	return r
}

